from safety_evals.loader import daily_flag_counts
from safety_evals.metrics import monitor_flag_rate, pooled_flag_rate, flags_in_window



def monitor_summary(groups, days):
    """Summary of groups of transcripts. See SPEC.md section 7."""
    all_events = [event for events in groups.values() for event in events]
    if all_events:
        first_day = min(event["day"] for event in all_events)
        last_day = max(event["day"] for event in all_events)
        recent = flags_in_window(daily_flag_counts(all_events, first_day, last_day), days)
    else:
        recent = 0

    non_empty_groups = sum(1 for events in groups.values() if events)
    return {
        "rate": round(pooled_flag_rate(groups), 3),
        "recent": recent,
        "groups": non_empty_groups,
    }



def top_flagged_groups(groups, n):
    """The groups with the highest flag rate. See SPEC.md section 8."""
    if n <= 0:
        return []

    ranked = sorted(
        (
            (name, monitor_flag_rate(events))
            for name, events in groups.items()
            if events
        ),
        key=lambda item: (-item[1], item[0]),
    )
    return [name for name, _rate in ranked[:n]]

import pytest

from safety_evals import (
    daily_flag_counts,
    dedupe_transcripts,
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    monitor_summary,
    parse_transcript_log,
    pooled_flag_rate,
    top_flagged_groups,
)



def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5



def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}, {"flagged": False}]) == pytest.approx(
        1 / 3
    )



def test_monitor_flag_rate_empty_is_zero():
    assert monitor_flag_rate([]) == 0.0



def test_pooled_flag_rate_weights_by_transcript_count():
    groups = {
        "a": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "b": [{"flagged": True}],
    }
    assert pooled_flag_rate(groups) == 0.5



def test_pooled_flag_rate_all_empty_groups_is_zero():
    assert pooled_flag_rate({"a": [], "b": []}) == 0.0



def test_flags_in_window_uses_last_days_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 10) == 6



def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]



def test_parse_transcript_log_handles_blank_comments_whitespace_and_empty_flag():
    lines = [
        "   ",
        "# comment",
        "   # another comment",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3, 5,   ",
    ]
    assert parse_transcript_log(lines) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]



def test_parse_transcript_log_error_mentions_input_line_number():
    with pytest.raises(ValueError, match="line 3"):
        parse_transcript_log(["# skip", "", "bad"])



def test_dedupe_transcripts_keeps_last_duplicate_id():
    events = [
        {"id": "b", "day": 4, "flagged": True},
        {"id": "a", "day": 3, "flagged": False},
        {"id": "b", "day": 2, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "b", "day": 2, "flagged": False},
        {"id": "a", "day": 3, "flagged": False},
    ]



def test_daily_flag_counts_inclusive_range_and_ignores_out_of_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 2, "flagged": True},
        {"id": "d", "day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 5) == [1, 0, 1, 0]
    assert daily_flag_counts(events, 5, 4) == []



def test_monitor_summary_basic():
    groups = {
        "g1": [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}],
        "g2": [],
        "g3": [{"id": "c", "day": 3, "flagged": True}],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}



def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [{"flagged": True}, {"flagged": False}],
        "c": [{"flagged": True}],
        "d": [],
    }
    assert top_flagged_groups(groups, 3) == ["c", "a", "b"]



def test_flag_rate_by_group_sorts_keys_and_uses_none_for_empty_groups():
    groups = {"b": [{"flagged": True}, {"flagged": False}], "a": [], "c": [{"flagged": False}]}
    assert flag_rate_by_group(groups) == {"a": None, "b": 0.5, "c": 0.0}



def test_longest_flag_streak_counts_positive_runs_only():
    assert longest_flag_streak([]) == 0
    assert longest_flag_streak([0, 2, 1, 0, 3, 4, 5, 0]) == 3
